import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import vm from "node:vm";

// The page is generated by our own server; slice its single inline script.
const html = readFileSync(0, "utf8"), start = html.indexOf("<script>") + "<script>".length;
const script = html.slice(start, html.indexOf("</script>", start));
class Element {
    constructor() { this.className = ""; this.textContent = ""; this.childNodes = []; }
    appendChild(child) { this.childNodes.push(child); child.parent = this; return child; }
    removeChild(child) { this.childNodes.splice(this.childNodes.indexOf(child), 1); }
    get firstChild() { return this.childNodes[0]; }
    remove() { this.parent?.removeChild(this); }
}
const root = new Element(), sockets = [];
class Socket {
    constructor() { this.events = {}; sockets.push(this); }
    addEventListener(name, fn) { this.events[name] = fn; }
    close() {}
}
vm.runInNewContext(script, {
    window: { setTimeout: () => 0, clearTimeout() {} },
    WebSocket: Socket, AbortController,
    location: { hostname: "localhost", protocol: "http:" },
    document: {
        getElementById: () => root,
        createElement: () => new Element(),
        documentElement: { style: { setProperty() {} } },
    },
    fetch: async () => ({ ok: false }),
});
// One caption as the core sends it (#1035), and the parts the page drew for it.
const drawn = (fields) => {
    sockets[0].events.message({ data: JSON.stringify({
        type: "REALTIME_SPEAKER", src_languages: {}, dst_languages: {},
        message: "original", translation: ["translated"], transliteration: [], ...fields,
    }) });
    return root.childNodes.at(-1).childNodes.map((part) => [part.className, part.textContent]);
};
const text = [["translation", "translated"], ["original", "original"]];

// A message of the shape before #1035, and one whose voices were not told apart: no speaker line.
assert.deepEqual(drawn({}), text);
assert.deepEqual(drawn({ speakers: [] }), text);
// The labels, above the text.
assert.deepEqual(drawn({ speakers: ["A", "B"] }), [["speaker", "A·B"], ...text]);
// The names, sent when the user chose so, stand for their labels.
assert.deepEqual(drawn({ speakers: ["A", "B"], speaker_names: { A: "Mika" } })[0], ["speaker", "Mika·B"]);
assert.deepEqual(drawn({ speakers: ["A"], speaker_names: {} })[0], ["speaker", "A"]);
// Only a string of the message's own names counts, never a key of every object.
assert.deepEqual(drawn({ speakers: ["A"], speaker_names: { A: 3 } })[0], ["speaker", "A"]);
assert.deepEqual(drawn({ speakers: ["toString"], speaker_names: {} })[0], ["speaker", "toString"]);
assert.deepEqual(drawn({ speakers: ["A"], speaker_names: "Mika" })[0], ["speaker", "A"]);
// A long line ends at 48 characters, counted as characters.
assert.deepEqual(drawn({ speakers: ["A"], speaker_names: { A: "😀".repeat(60) } })[0], ["speaker", `${"😀".repeat(47)}…`]);
console.log("OBS speakers: labels, chosen names, the old shape and the length passed");
